 private final Activity activity;private final ChatSession session;private final JSONObject state;private final Host host;private final Handler handler=new Handler(Looper.getMainLooper());
 private int bg,card,ink,muted,accent,line,soft;private boolean dark;private LinearLayout root,panel;private String page="home";private BooleanSupplier dirty=()->false;private BooleanSupplier saveAction;private TextView error;private JSONObject editing;
