 private int dp(float x){return (int)(x*activity.getResources().getDisplayMetrics().density+.5f);}
 private void colors(){String theme=state.optString("theme","system");dark=theme.equals("dark")||theme.equals("system")&&(activity.getResources().getConfiguration().uiMode&48)==32;bg=Color.parseColor(dark?"#111b18":"#f7f9f6");card=Color.parseColor(dark?"#1a2821":"#ffffff");ink=Color.parseColor(dark?"#e1ebe4":"#223a31");muted=Color.parseColor(dark?"#92a59a":"#5f7265");accent=Color.parseColor(dark?"#93cbb0":"#276a52");line=Color.parseColor(dark?"#2b3a32":"#e3eae3");soft=Color.parseColor(dark?"#22382c":"#edf4ed");}
 private LinearLayout col(){LinearLayout x=new LinearLayout(activity);x.setOrientation(LinearLayout.VERTICAL);return x;}private LinearLayout row(){LinearLayout x=new LinearLayout(activity);x.setGravity(Gravity.CENTER_VERTICAL);return x;}
 private LinearLayout.LayoutParams lp(int width,int height){return new LinearLayout.LayoutParams(width<0?width:dp(width),height<0?height:dp(height));}
