 private void item(String glyph,String title,String caption,Runnable action){LinearLayout tile=row();tile.setPadding(dp(14),dp(15),dp(12),dp(15));tile.setBackground(UiKit.surface(card,line,dp(17),0x12236f5b));TextView mark=text("",14,accent);mark.setCompoundDrawables(icon(glyph,accent,21),null,null,null);tile.addView(mark,lp(30,30));LinearLayout copy=col();copy.setPadding(dp(10),0,dp(8),0);TextView heading=text(title,15,ink);heading.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));copy.addView(heading);if(!caption.isEmpty()){TextView detail=text(caption,12,muted);detail.setPadding(0,dp(4),0,0);detail.setMaxLines(3);detail.setEllipsize(TextUtils.TruncateAt.END);copy.addView(detail);}tile.addView(copy,new LinearLayout.LayoutParams(0,-2,1));TextView next=text("",12,muted);next.setCompoundDrawables(icon("next",muted,16),null,null,null);tile.addView(next);tile.setFocusable(true);tile.setContentDescription(title+"，"+caption);tile.setOnClickListener(v->action.run());panel.addView(tile,lp(-1,-2));gap(9);}
 private EditText field(String label,String value,String placeholder,int minLines,int max){label(label);EditText e=new EditText(activity);e.setTextSize(15);e.setTextColor(ink);e.setHintTextColor(muted);e.setHint(placeholder);e.setContentDescription(label);e.setText(value);e.setGravity(Gravity.TOP);e.setPadding(dp(13),dp(12),dp(13),dp(12));e.setBackground(UiKit.surface(soft,0,dp(12),0));e.setMinLines(minLines);e.setMaxLines(Math.max(minLines,7));e.setInputType(minLines==1?1:android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);if(minLines==1)e.setSingleLine(true);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(max)});panel.addView(e,lp(-1,-2));return e;}
 private void toggle(String title,String caption,boolean checked,Consumer<Boolean> update){LinearLayout box=col();box.setPadding(dp(14),dp(9),dp(14),dp(9));box.setBackground(UiKit.surface(card,line,dp(17),0));Switch value=new Switch(activity);value.setText(title);value.setTextSize(15);value.setTextColor(ink);value.setContentDescription(title);value.setMinHeight(dp(44));value.setChecked(checked);box.addView(value,lp(-1,-2));TextView detail=text(caption,12,muted);detail.setPadding(0,0,dp(24),dp(7));box.addView(detail);value.setOnCheckedChangeListener((v,on)->update.accept(on));panel.addView(box,lp(-1,-2));gap(10);}
 private void fail(Exception e){if(error!=null){error.setText(e.getMessage()==null?"保存失败，请重试":e.getMessage());error.setVisibility(View.VISIBLE);}else dialog().setMessage(e.getMessage()).setPositiveButton("关闭",null).show();}
