 private void hideKeyboard(){View focus=getCurrentFocus();if(focus!=null)((InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(focus.getWindowToken(),0);}
 private String parent(){if(page.equals("profile")||page.equals("preferences")||page.equals("memories"))return "personal";if(page.equals("memory-edit"))return "memories";return "home";}
 private void back(){hideKeyboard();String target=parent();if(dirty.getAsBoolean()){dialog().setTitle("保存修改？").setMessage("你刚才编辑的内容还没有保存。").setPositiveButton("保存并返回",(d,w)->{if(saveAction!=null&&saveAction.getAsBoolean()){if(page.equals("home"))dismiss();else render(target);}}).setNeutralButton("放弃修改",(d,w)->{if(page.equals("home"))dismiss();else render(target);}).setNegativeButton("继续编辑",null).show();}else if(page.equals("home"))dismiss();else render(target);}
